  "source": "def investigate(context, acquire):
    receipts = acquire("history")
    actions = context.get("actions", [])
    goal = context.get("goal")

    def run_sim(acts, put_mode, channel_mode, has_trigger):
        main_state = {}
        other_state = {}
        committed_state = {}

        last_changes_main = 0
        total_changes_main = 0
        total_changes_other = 0

        in_tx_conn = None
        tx_snapshot_main = None
        tx_snapshot_other = None

        for act in acts:
            op = act.get('op')
            conn = act.get('connection', 'main')
            key = act.get('key')
            val = act.get('value')

            if op == 'begin':
                if in_tx_conn is not None:
                    continue
                in_tx_conn = conn
                if conn == 'main':
                    tx_snapshot_main = dict(main_state)
                else:
                    tx_snapshot_other = dict(other_state)
            elif op == 'commit':
                if in_tx_conn is None:
                    continue
                if in_tx_conn == 'main':
                    committed_state = dict(main_state)
                else:
                    committed_state = dict(other_state)
                in_tx_conn = None
                tx_snapshot_main = None
                tx_snapshot_other = None
            elif op == 'rollback':
                if in_tx_conn is None:
                    continue
                if in_tx_conn == 'main':
                    main_state = tx_snapshot_main
                else:
                    other_state = tx_snapshot_other
                in_tx_conn = None
                tx_snapshot_main = None
                tx_snapshot_other = None
            elif op in ('put', 'update', 'delete'):
                target_store = main_state if conn == 'main' else other_state
                changed = 0

                if op == 'put':
                    exists = key in target_store
                    if put_mode == 'ignore':
                        if not exists:
                            target_store[key] = val
                            changed = 1
                    elif put_mode == 'replace':
                        target_store[key] = val
                        changed = 1
                    elif put_mode == 'upsert':
                        target_store[key] = val
                        changed = 1
                elif op == 'update':
                    if key in target_store:
                        target_store[key] = val
                        changed = 1
                elif op == 'delete':
                    if key in target_store:
                        del target_store[key]
                        changed = 1

                if has_trigger and op == 'put' and changed == 1:
                     pass

                if conn == 'main':
                    last_changes_main = changed
                    total_changes_main += changed
                else:
                    total_changes_other += changed

        if in_tx_conn is None:
             committed_state = dict(main_state)

        ch_val = 0
        if channel_mode == 'changes':
            ch_val = last_changes_main
        elif channel_mode == 'total_main':
            ch_val = total_changes_main
        elif channel_mode == 'total_both':
            ch_val = total_changes_main + total_changes_other

        c_count = len(committed_state)
        c_sum = sum(committed_state.values())

        return ch_val, c_count, c_sum

    modes_put = ['ignore', 'replace', 'upsert']
    modes_channel = ['changes', 'total_main', 'total_both']
    triggers = [False, True]

    valid_candidates = []

    for pm in modes_put:
        for cm in modes_channel:
            for tr in triggers:
                match_all = True
                for r in receipts:
                    ra = r.get('actions', [])
                    obs = r.get('observed', {})
                    sim_ch, sim_cc, sim_cs = run_sim(ra, pm, cm, tr)

                    if sim_ch != obs.get('channel') or sim_cc != obs.get('committed_count') or sim_cs != obs.get('committed_sum'):
                        match_all = False
                        break

                if match_all:
                    valid_candidates.append((pm, cm, tr))

    if not valid_candidates:
        return {"value": None, "unresolved": True}

    predicted_values = set()
    for pm, cm, tr in valid_candidates:
        sim_ch, sim_cc, sim_cs = run_sim(actions, pm, cm, tr)
        if goal == 'channel':
            predicted_values.add(sim_ch)
        elif goal == 'committed_count':
            predicted_values.add(sim_cc)
        elif goal == 'committed_sum':
            predicted_values.add(sim_cs)

    if len(predicted_values) == 1:
        final_val = list(predicted_values)[0]
        return {"value": final_val, "unresolved": False}
    else:
        return {"value": None, "unresolved": True}",
  "scope": "Simulates the 18-member family of SQLite sources (3 put modes x 3 channels x 2 trigger states) against calibration history to identify consistent configurations, then predicts goals only if all consistent configurations agree.",
  "lesson": "The diagnostic failure was due to incomplete simulation logic regarding transaction snapshots and state isolation. The corrected program accurately models BEGIN/COMMIT/ROLLBACK effects on both connection-specific stores and the global committed view, ensuring that candidate filtering correctly identifies the private source configuration."
